// Wave76 admitted all five unchanged API53 successor04 methods, including errors and rollback.
func TestRunLeadContactRoleContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadContactRole53.cls"), "@IsTest private class GladeLeadContactRole53 {\n private static void assertRoles(Database.LeadConvertResult result,Boolean omitOpportunity){\n  List<OpportunityContactRole> roles=[SELECT Id,OpportunityId,ContactId,IsPrimary FROM OpportunityContactRole];\n  if(omitOpportunity){System.assertEquals(null,result.getOpportunityId());System.assertEquals(0,roles.size());System.assertEquals(0,[SELECT count() FROM Opportunity]);return;}\n  System.assertNotEquals(null,result.getOpportunityId());System.assertEquals(1,roles.size(),'One native conversion role');\n  System.assertNotEquals(null,roles[0].Id);System.assertEquals(result.getOpportunityId(),roles[0].OpportunityId);\n  System.assertEquals(result.getContactId(),roles[0].ContactId);System.assertEquals(true,roles[0].IsPrimary);\n  Id opportunityId=result.getOpportunityId();\n  Opportunity opportunity=[SELECT Id,AccountId,Name FROM Opportunity WHERE Id=:opportunityId];\n  System.assertEquals(result.getAccountId(),opportunity.AccountId);System.assertEquals('Test Opp',opportunity.Name);\n  System.assertEquals(1,[SELECT count() FROM Opportunity]);\n }\n private static void convertAndAssert(Boolean existingAccount,Boolean existingContact,Boolean omitOpportunity){\n  Account account;\n  Contact contact;\n  if(existingAccount){account=new Account(Name='Owned conversion account');insert account;}\n  if(existingContact){contact=new Contact(FirstName='Testy',LastName='Testy',AccountId=account.Id);insert contact;}\n  Lead source=new Lead(FirstName='Testy',LastName='Testy',Company='Owned conversion account');insert source;\n  Database.LeadConvert request=new Database.LeadConvert();request.setLeadId(source.Id);\n  if(!omitOpportunity)request.setOpportunityName('Test Opp');request.setDoNotCreateOpportunity(omitOpportunity);\n  request.setOwnerId(UserInfo.getUserId());request.setSendNotificationEmail(false);\n  if(existingAccount)request.setAccountId(account.Id);\n  if(existingContact)request.setContactId(contact.Id);\n  LeadStatus converted=[SELECT ApiName FROM LeadStatus WHERE IsConverted=true LIMIT 1];request.setConvertedStatus(converted.ApiName);\n  System.assertEquals(0,[SELECT count() FROM OpportunityContactRole]);\n  Test.startTest();Database.LeadConvertResult result=Database.convertLead(request);\n  System.assertEquals(true,result.isSuccess());System.assertEquals(source.Id,result.getLeadId());\n  if(existingAccount)System.assertEquals(account.Id,result.getAccountId());\n  if(existingContact)System.assertEquals(contact.Id,result.getContactId());\n  assertRoles(result,omitOpportunity);\n  Test.stopTest();assertRoles(result,omitOpportunity);\n  Lead loaded=[SELECT IsConverted,ConvertedAccountId,ConvertedContactId,ConvertedOpportunityId FROM Lead WHERE Id=:source.Id];\n  System.assertEquals(true,loaded.IsConverted);System.assertEquals(result.getAccountId(),loaded.ConvertedAccountId);\n  System.assertEquals(result.getContactId(),loaded.ConvertedContactId);System.assertEquals(result.getOpportunityId(),loaded.ConvertedOpportunityId);\n  System.assertEquals(1,[SELECT count() FROM Contact]);System.assertEquals(1,[SELECT count() FROM Account]);\n }\n @IsTest static void newTargetsCreatePrimaryRole(){convertAndAssert(false,false,false);}\n @IsTest static void existingTargetsCreatePrimaryRole(){convertAndAssert(true,true,false);}\n @IsTest static void existingAccountNewContactRole(){convertAndAssert(true,false,false);}\n @IsTest static void omittedOpportunityCreatesNoRole(){convertAndAssert(true,true,true);}\n @IsTest static void omittedOpportunityWithNameRejected(){\n  Account account=new Account(Name='Owned conversion account');insert account;\n  Contact contact=new Contact(FirstName='Testy',LastName='Testy',AccountId=account.Id);insert contact;\n  Lead source=new Lead(FirstName='Testy',LastName='Testy',Company='Owned conversion account');insert source;\n  Database.LeadConvert request=new Database.LeadConvert();request.setLeadId(source.Id);\n  request.setOpportunityName('Test Opp');request.setDoNotCreateOpportunity(true);\n  request.setOwnerId(UserInfo.getUserId());request.setSendNotificationEmail(false);\n  request.setAccountId(account.Id);request.setContactId(contact.Id);\n  LeadStatus converted=[SELECT ApiName FROM LeadStatus WHERE IsConverted=true LIMIT 1];request.setConvertedStatus(converted.ApiName);\n  Boolean rejected=false;\n  Test.startTest();\n  try{Database.convertLead(request);}catch(DmlException error){\n   rejected=true;\n   System.assertEquals('System.DmlException',error.getTypeName(),'getTypeName');\n   System.assertEquals(1,error.getNumDml(),'getNumDml');\n   System.assertEquals(StatusCode.INVALID_FIELD,error.getDmlType(0),'getDmlType');\n   System.assertEquals(new List<String>{'Id'},error.getDmlFieldNames(0),'getDmlFieldNames');\n   System.assertEquals(null,error.getDmlFields(0),'getDmlFields');\n   System.assertEquals('One or more leads couldn\\'t be converted. If doNotCreateOpportunity is true, opportunityName and opportunityId must be null.',error.getDmlMessage(0),'getDmlMessage');\n  }\n  Test.stopTest();\n  System.assertEquals(true,rejected,'Invalid option combination must fail');\n  Lead unchanged=[SELECT IsConverted FROM Lead WHERE Id=:source.Id];\n  System.assertEquals(false,unchanged.IsConverted,'Lead remains unconverted');\n  System.assertEquals(0,[SELECT count() FROM Opportunity],'Opportunity population');\n  System.assertEquals(0,[SELECT count() FROM OpportunityContactRole],'Role population');\n  System.assertEquals(1,[SELECT count() FROM Contact],'Contact population');\n  System.assertEquals(1,[SELECT count() FROM Account],'Account population');\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadContactRole53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 5 || got.Passed != 5 || got.Skipped != 0 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("lead contact role contracts failed: %s", data)
	}
}
